import{_ as t}from"./chunks/prontera-city.B6XwNokk.js";import{_ as e}from"./chunks/prontera-street.BZRjh5Zm.js";import{_ as r,o as l,c as o,ag as i}from"./chunks/framework.DGzMGr_a.js";const m=JSON.parse('{"title":"游戏背景与世界观","description":"RO3故事背景设定，多元宇宙世界观、核心剧情、Blagis角色介绍。","frontmatter":{"title":"游戏背景与世界观","description":"RO3故事背景设定，多元宇宙世界观、核心剧情、Blagis角色介绍。","lastUpdated":true},"headers":[],"relativePath":"guide/lore.md","filePath":"guide/lore.md","lastUpdated":1780229775000}'),s={name:"guide/lore.md"};function d(n,a,h,u,c,p){return l(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="游戏背景与世界观" tabindex="-1">游戏背景与世界观 <a class="header-anchor" href="#游戏背景与世界观" aria-label="Permalink to &quot;游戏背景与世界观&quot;">​</a></h1><p><img src="'+t+'" alt="RO3 普隆德拉城市全景"></p><h2 id="故事背景" tabindex="-1">故事背景 <a class="header-anchor" href="#故事背景" aria-label="Permalink to &quot;故事背景&quot;">​</a></h2><p>在《RO 仙境传说 3》的世界中，米德加尔特大陆再次陷入了动荡。随着「时序之庭」的开启，平行宇宙之间的壁垒被打破，玩家将踏上一段跨越多元宇宙的史诗旅程。</p><h3 id="多元宇宙设定" tabindex="-1">多元宇宙设定 <a class="header-anchor" href="#多元宇宙设定" aria-label="Permalink to &quot;多元宇宙设定&quot;">​</a></h3><p>RO3打破了传统单一世界束缚，引入了**多元宇宙（Multiverse）**设定：</p><ul><li><strong>核心世界</strong>：延续经典RO的米德加尔特大陆，普隆德拉、梦罗克等经典城市以全新3D技术重制</li><li><strong>平行世界</strong>：每个精心打造的世界都拥有独特的文明风貌、沉浸式剧情和极具特色的挑战</li><li><strong>时序之庭</strong>：连接各个平行宇宙的枢纽，也是玩家穿越世界的起点</li></ul><h3 id="穿越与成长" tabindex="-1">穿越与成长 <a class="header-anchor" href="#穿越与成长" aria-label="Permalink to &quot;穿越与成长&quot;">​</a></h3><p>每次穿越到新的平行世界，角色将获得：</p><ul><li>全新的职业特质和养成搭配</li><li>不同的战斗体验和流派组合</li><li>避免数值膨胀的赛季制平衡</li></ul><blockquote><p>玩家可以随时选择一个全新世界重新启程，在熟悉的RO世界中体验全新的冒险乐趣。</p></blockquote><h2 id="关键角色" tabindex="-1">关键角色 <a class="header-anchor" href="#关键角色" aria-label="Permalink to &quot;关键角色&quot;">​</a></h2><h3 id="新主角-blagis-暂定名" tabindex="-1">新主角：Blagis（暂定名） <a class="header-anchor" href="#新主角-blagis-暂定名" aria-label="Permalink to &quot;新主角：Blagis（暂定名）&quot;">​</a></h3><p>根据制作人访谈，RO3将引入一位名为<strong>Blagis</strong>的新角色，他将是引导玩家穿越多元宇宙的关键人物。</p><h3 id="经典角色回归" tabindex="-1">经典角色回归 <a class="header-anchor" href="#经典角色回归" aria-label="Permalink to &quot;经典角色回归&quot;">​</a></h3><ul><li>经典的NPC和怪物将以全新形象回归</li><li>普隆德拉的冒险者公会、大教堂、图书馆等标志性场景全部3D重制</li></ul><h2 id="赛季制与剧情" tabindex="-1">赛季制与剧情 <a class="header-anchor" href="#赛季制与剧情" aria-label="Permalink to &quot;赛季制与剧情&quot;">​</a></h2><h3 id="赛季推进故事" tabindex="-1">赛季推进故事 <a class="header-anchor" href="#赛季推进故事" aria-label="Permalink to &quot;赛季推进故事&quot;">​</a></h3><p>RO3的赛季制（每赛季3-4个月）不仅是玩法更新机制，也是剧情的推进方式：</p><table tabindex="0"><thead><tr><th>赛季</th><th>主题</th><th>内容</th></tr></thead><tbody><tr><td>S1</td><td>米德加尔特的觉醒</td><td>主线剧情、基础职业</td></tr><tr><td>S2</td><td>平行世界的入侵</td><td>新世界、新副本</td></tr><tr><td>S3+</td><td>多元宇宙的战争</td><td>GVG拓展、领地战</td></tr></tbody></table><h3 id="共创计划" tabindex="-1">共创计划 <a class="header-anchor" href="#共创计划" aria-label="Permalink to &quot;共创计划&quot;">​</a></h3><p>RO3推出了「全球玩家共创计划」，涵盖：</p><ul><li><strong>职业共创</strong>：玩家参与职业平衡和设计</li><li><strong>玩法共创</strong>：核心玩法反馈</li><li><strong>数值共创</strong>：平衡性调整</li></ul><blockquote><p>开发团队强调：「我们既要让老玩家找回当年的感动，也要让新玩家感受RO冒险世界的独特魅力。」</p></blockquote><h2 id="美术风格" tabindex="-1">美术风格 <a class="header-anchor" href="#美术风格" aria-label="Permalink to &quot;美术风格&quot;">​</a></h2><h3 id="手绘描线-新复古渲染" tabindex="-1">手绘描线 + 新复古渲染 <a class="header-anchor" href="#手绘描线-新复古渲染" aria-label="Permalink to &quot;手绘描线 + 新复古渲染&quot;">​</a></h3><p>RO3的美术风格可以概括为：</p><ul><li><strong>经典传承</strong>：保留RO原作的笔触感和角色比例</li><li><strong>现代升级</strong>：从2D提升到3D，角色发丝、服饰纹理清晰可见</li><li><strong>动态世界</strong>：动态天气系统与昼夜循环</li><li><strong>城市重制</strong>：普隆德拉等经典城市每砖每瓦重新诠释</li></ul><p><img src="'+e+'" alt="RO3 普隆德拉街景"></p><blockquote><p>当玩家走在重制的普隆德拉街道上——道具店、大教堂、区公所、图书馆、骑士公会——每一个场景都在唤醒当年的记忆。</p></blockquote>',30)])])}const _=r(s,[["render",d]]);export{m as __pageData,_ as default};
